system.handler.AndroidTimerServiceimport com.roshan.persona.system.handler.AndroidUrlLauncherServiceimport com.roshan.persona.system.handler.AndroidWifiServiceimport com.roshan.persona.system.handler.AppHandlerimport com.roshan.persona.system.handler.AppLauncherServiceimport com.roshan.persona.system.handler.AppNameMatcherimport com.roshan.persona.system.handler.AirplaneModeHandlerimport com.roshan.persona.system.handler.AirplaneModeServiceimport com.roshan.persona.system.handler.AudioServiceimport com.roshan.persona.system.handler.AudioStateProbeimport com.roshan.persona.system.handler.BatterySaverHandlerimport com.roshan.persona.system.handler.BatterySaverServiceimport com.roshan.persona.system.handler.BluetoothHandlerimport com.roshan.persona.system.handler.BluetoothServiceimport com.roshan.persona.system.handler.BrightnessHandlerimport com.roshan.persona.system.handler.ClipboardHandlerimport com.roshan.persona.system.handler.ClipboardServiceimport com.roshan.persona.system.handler.CameraServiceimport com.roshan.persona.system.handler.DisplayServiceimport com.roshan.persona.system.handler.DnDHandlerimport com.roshan.persona.system.handler.DnDServiceimport com.roshan.persona.system.handler.LocationHandlerimport com.roshan.persona.system.handler.LocationServiceimport com.roshan.persona.system.handler.NfcHandlerimport com.roshan.persona.system.handler.NfcServiceimport com.roshan.persona.system.handler.NoopAccessibilityServiceimport com.roshan.persona.system.handler.NousAccessibilityServiceInterfaceimport com.roshan.persona.system.handler.NotificationHandlerimport com.roshan.persona.system.handler.NotificationServiceimport com.roshan.persona.system.handler.RegistryBackedAccessibilityServiceimport com.roshan.persona.system.handler.ReversibleHandlerimport com.roshan.persona.system.handler.RingerHandlerimport com.roshan.persona.system.handler.ScreenHandlerimport com.roshan.persona.system.handler.SystemOperationHandlerimport com.roshan.persona.system.handler.TetheringHandlerimport com.roshan.persona.system.handler.TetheringServiceimport com.roshan.persona.system.handler.TimerHandlerimport com.roshan.persona.system.handler.TimerServiceimport com.roshan.persona.system.handler.TorchHandlerimport com.roshan.persona.system.handler.UrlHandlerimport com.roshan.persona.system.handler.UrlLauncherServiceimport com.roshan.persona.system.handler.VolumeHandlerimport com.roshan.persona.system.handler.WifiHandlerimport com.roshan.persona.system.handler.WifiServiceimport com.roshan.persona.system.undo.PersistentUndoStackimport com.roshan.persona.system.undo.SystemOperationSerializerimport com.roshan.persona.system.util.ForegroundActivityTrackerimport com.roshan.persona.system.util.SettingsHelperimport com.roshan.persona.system.util.ThermalGateimport dagger.Moduleimport dagger.Providesimport dagger.hilt.InstallInimport dagger.hilt.android.qualifiers.ApplicationContextimport dagger.hilt.components.SingletonComponentimport javax.inject.Singleton/** * NOUS — System Hilt Module (Module 10 v2 — Step 10.9 FINAL). * * Wires every system component to its concrete implementation and provides: *  - All 19 operation handlers (Torch, Volume, Ringer, Brightness, Screen, *    Wifi, Bluetooth, AirplaneMode, Location, Tethering, Nfc, App, Url, *    Clipboard, Alarm, Timer, Notification, DnD, BatterySaver). *  - All Android service wrappers (AudioService, CameraService, etc.). *  - The handler registry map (Class<SystemOperation> → handler). *  - [SystemOperationExecutorImpl] — implements Brain's interface. *  - [PersistentUndoStack] — Room DB-backed undo. *  - [AtomicBatchCoordinator] — parallel/sequential batch with rollback. *  - [SystemFacade] — single entry point for UI + Brain. *  - [PermissionChecker] — NOW PROVIDED BY :feature:security's SecurityModule *    (Strategy §12.1). SystemModule injects but does not provide. *  - [ThermalGate] — thermal pre-flight for hardware-heavy ops. * * ## Brain wiring (replaces FakeSystemOperationExecutor) * * Brain's `SkillInfrastructureModule` no longer provides * `SystemOperationExecutor` — this module provides the real * [SystemOperationExecutorImpl]. Brain skills (TorchSkill, VolumeSkill, etc.) * consume the interface; they don't know whether the impl is fake or real. */@Module@InstallIn(SingletonComponent::class)object SystemModule {    // ─── Android system services (from Context) ──────────────────────────    // All casts use safe `as?` + require() to fail fast with a clear message    // rather than ClassCastException at runtime.    @Provides @Singleton    fun provideAudioManager(@ApplicationContext context: Context): AudioManager =        context.getSystemService(Context.AUDIO_SERVICE) as? AudioManager            ?: error("AudioManager unavailable")    @Provides @Singleton    fun provideCameraManager(@ApplicationContext context: Context): CameraManager =        context.getSystemService(Context.CAMERA_SERVICE) as? CameraManager            ?: error("CameraManager unavailable")    @Provides @Singleton    fun providePowerManager(@ApplicationContext context: Context): PowerManager =        context.getSystemService(Context.POWER_SERVICE) as? PowerManager            ?: error("PowerManager unavailable")    @Provides @Singleton    fun provideNotificationManager(@ApplicationContext context: Context): NotificationManager =        context.getSystemService(Context.NOTIFICATION_SERVICE) as? NotificationManager            ?: error("NotificationManager unavailable")    @Provides @Singleton    fun provideWifiManager(@ApplicationContext context: Context): WifiManager? =        context.getSystemService(Context.WIFI_SERVICE) as? WifiManager    @Provides @Singleton    fun provideBluetoothManager(@ApplicationContext context: Context): BluetoothManager? =        context.getSystemService(Context.BLUETOOTH_SERVICE) as? BluetoothManager    @Provides @Singleton    fun provideConnectivityManager(@ApplicationContext context: Context): ConnectivityManager =        context.getSystemService(Context.CONNECTIVITY_SERVICE) as? ConnectivityManager            ?: error("ConnectivityManager unavailable")    // ─── Utility services ─────────────────────────────────────────────────    @Provides @Singleton    fun provideSettingsHelper(@ApplicationContext context: Context): SettingsHelper =        SettingsHelper(context)    @Provides @Singleton    fun provideThermalGate(powerManager: PowerManager): ThermalGate =        ThermalGate(powerManager)    // ─── PermissionChecker — PROVIDED BY :feature:security's SecurityModule ───    // Strategy §12.1 + §14.2 Table 10: Module 12 (Security) now provides the    // canonical RealPermissionChecker (backed by ContextCompat.checkSelfPermission)    // for the entire app. SystemModule no longer provides it — avoids Hilt    // duplicate binding.    //    // NOTE: SystemOperationExecutorImpl still injects PermissionChecker; Hilt    // resolves it to :feature:security's binding automatically.    // ─── Service interfaces ───────────────────────────────────────────────    @Provides @Singleton    fun provideAudioService(audioManager: AudioManager): AudioService =        AndroidAudioService(audioManager)    @Provides @Singleton    fun provideAudioStateProbe(        @ApplicationContext context: Context, audioManager: AudioManager,    ): AudioStateProbe = AndroidAudioStateProbe(context, audioManager)    @Provides @Singleton    fun provideCameraService(cameraManager: CameraManager): CameraService =        AndroidCameraService(cameraManager)    @Provides @Singleton    fun provideDisplayService(        @ApplicationContext context: Context,        tracker: com.roshan.persona.system.util.ForegroundActivityTracker,    ): DisplayService =        AndroidDisplayService(context) { tracker.currentActivity }    @Provides @Singleton    fun provideWifiService(@ApplicationContext context: Context, wifiManager: WifiManager?): WifiService =        AndroidWifiService(context, wifiManager)    @Provides @Singleton    fun provideBluetoothService(@ApplicationContext context: Context, bluetoothManager: BluetoothManager?): BluetoothService =        AndroidBluetoothService(context, bluetoothManager)    @Provides @Singleton    fun provideAirplaneModeService(@ApplicationContext context: Context, settingsHelper: SettingsHelper): AirplaneModeService =        AndroidAirplaneModeService(context, settingsHelper)    @Provides @Singleton    fun provideLocationService(@ApplicationContext context: Context, settingsHelper: SettingsHelper): LocationService =        AndroidLocationService(context, settingsHelper)    @Provides @Singleton    fun provideTetheringService(@ApplicationContext context: Context): TetheringService =        AndroidTetheringService(context)    @Provides @Singleton    fun provideNfcService(@ApplicationContext context: Context, settingsHelper: SettingsHelper): NfcService =        AndroidNfcService(context, settingsHelper)    @Provides @Singleton    fun provideAppLauncherService(@ApplicationContext context: Context): AppLauncherService =        AndroidAppLauncherService(context, context.packageManager, AppNameMatcher())    @Provides @Singleton    fun provideUrlLauncherService(@ApplicationContext context: Context): UrlLauncherService =        AndroidUrlLauncherService(context)    @Provides @Singleton    fun provideClipboardService(@ApplicationContext context: Context): ClipboardService {        val cm = context.getSystemService(Context.CLIPBOARD_SERVICE) as? android.content.ClipboardManager            ?: error("ClipboardManager unavailable")        return AndroidClipboardService(cm)    }    @Provides @Singleton    fun provideAlarmClockService(@ApplicationContext context: Context): AlarmClockService =        AndroidAlarmClockService(context)    @Provides @Singleton    fun provideTimerService(@ApplicationContext context: Context): TimerService =        AndroidTimerService(context)    @Provides @Singleton    fun provideNotificationService(@ApplicationContext context: Context, nm: NotificationManager): NotificationService =        AndroidNotificationService(context, nm)    @Provides @Singleton    fun provideDnDService(nm: NotificationManager): DnDService = AndroidDnDService(nm)    @Provides @Singleton    fun provideBatterySaverService(pm: PowerManager): BatterySaverService =        AndroidBatterySaverService(pm)    @Provides @Singleton    fun provideAccessibilityService(): NousAccessibilityServiceInterface =        RegistryBackedAccessibilityService()    // ─── Handlers (19 total) ──────────────────────────────────────────────    @Provides @Singleton fun provideTorchHandler(svc: CameraService): TorchHandler = TorchHandler(svc)    @Provides @Singleton fun provideVolumeHandler(a: AudioService, p: AudioStateProbe): VolumeHandler = VolumeHandler(a, p)    @Provides @Singleton fun provideRingerHandler(svc: AudioService): RingerHandler = RingerHandler(svc)    @Provides @Singleton fun provideBrightnessHandler(svc: DisplayService): BrightnessHandler = BrightnessHandler(svc)    @Provides @Singleton fun provideScreenHandler(a: NousAccessibilityServiceInterface, d: DisplayService): ScreenHandler = ScreenHandler(a, d)    @Provides @Singleton fun provideWifiHandler(svc: WifiService): WifiHandler = WifiHandler(svc)    @Provides @Singleton fun provideBluetoothHandler(svc: BluetoothService): BluetoothHandler = BluetoothHandler(svc)    @Provides @Singleton fun provideAirplaneModeHandler(svc: AirplaneModeService): AirplaneModeHandler = AirplaneModeHandler(svc)    @Provides @Singleton fun provideLocationHandler(svc: LocationService): LocationHandler = LocationHandler(svc)    @Provides @Singleton fun provideTetheringHandler(svc: TetheringService): TetheringHandler = TetheringHandler(svc)    @Provides @Singleton fun provideNfcHandler(svc: NfcService): NfcHandler = NfcHandler(svc)    @Provides @Singleton fun provideAppHandler(svc: AppLauncherService): AppHandler = AppHandler(svc)    @Provides @Singleton fun provideUrlHandler(svc: UrlLauncherService): UrlHandler = UrlHandler(svc)    @Provides @Singleton fun provideClipboardHandler(svc: ClipboardService): ClipboardHandler = ClipboardHandler(svc)    @Provides @Singleton fun provideAlarmHandler(svc: AlarmClockService): AlarmHandler = AlarmHandler(svc)    @Provides @Singleton fun provideTimerHandler(svc: TimerService): TimerHandler = TimerHandler(svc)    @Provides @Singleton fun provideNotificationHandler(svc: NotificationService): NotificationHandler = NotificationHandler(svc)    @Provides @Singleton fun provideDnDHandler(svc: DnDService): DnDHandler = DnDHandler(svc)    @Provides @Singleton fun provideBatterySaverHandler(svc: BatterySaverService): BatterySaverHandler = BatterySaverHandler(svc)    // ─── Handler registry (for executor dispatch) ─────────────────────────    @Provides @Singleton    fun provideHandlerRegistry(        torch: TorchHandler, volume: VolumeHandler, ringer: RingerHandler,        brightness: BrightnessHandler, screen: ScreenHandler, wifi: WifiHandler,        bluetooth: BluetoothHandler, airplane: AirplaneModeHandler, location: LocationHandler,        tethering: TetheringHandler, nfc: NfcHandler, app: AppHandler, url: UrlHandler,        clipboard: ClipboardHandler, alarm: AlarmHandler, timer: TimerHandler,        notification: NotificationHandler, dnd: DnDHandler, batterySaver: BatterySaverHandler,    ): Map<Class<out SystemOperation>, @JvmSuppressWildcards SystemOperationHandler<*>> {        return mapOf(            SystemOperation.SetTorch::class.java to torch,            SystemOperation.AdjustVolume::class.java to volume,            SystemOperation.SetVolume::class.java to volume,            SystemOperation.SetRingerMode::class.java to ringer,            SystemOperation.SetDisplayBrightness::class.java to brightness,            SystemOperation.LockScreen::class.java to screen,            SystemOperation.SetKeepScreenOn::class.java to screen,            SystemOperation.SetWifi::class.java to wifi,            SystemOperation.SetBluetooth::class.java to bluetooth,            SystemOperation.SetAirplaneMode::class.java to airplane,            SystemOperation.SetLocationMode::class.java to location,            SystemOperation.SetTethering::class.java to tethering,            SystemOperation.SetNfc::class.java to nfc,            SystemOperation.OpenApp::class.java to app,            SystemOperation.OpenUrl::class.java to url,            SystemOperation.CopyToClipboard::class.java to clipboard,            SystemOperation.SetAlarm::class.java to alarm,            SystemOperation.SetTimer::class.java to timer,            SystemOperation.SetDndMode::class.java to dnd,            SystemOperation.SetBatterySaver::class.java to batterySaver,            SystemOperation.PostNotification::class.java to notification,        )    }    // ─── Executor + undo + batch ──────────────────────────────────────────    @Provides @Singleton    fun providePreStateStore(): PreStateStore = InMemoryPreStateStore()    @Provides @Singleton    fun provideSystemOperationExecutorImpl(        handlers: Map<Class<out SystemOperation>, @JvmSuppressWildcards SystemOperationHandler<*>>,        permissionChecker: PermissionChecker, thermalGate: ThermalGate, preStateStore: PreStateStore,    ): SystemOperationExecutorImpl = SystemOperationExecutorImpl(handlers, permissionChecker, thermalGate, preStateStore)    @Provides @Singleton    fun provideSystemOperationExecutor(impl: SystemOperationExecutorImpl): SystemOperationExecutor = impl    @Provides @Singleton    fun providePersistentUndoStack(        dao: UndoActionDao,        handlers: Map<Class<out SystemOperation>, @JvmSuppressWildcards SystemOperationHandler<*>>,    ): PersistentUndoStack {        // Build a handler-id → handler lookup for per-handler pre-state serialization        // (audit defect B fix). Only ReversibleHandlers are included — others have        // no pre-state to serialize.        val byId: Map<String, ReversibleHandler<*>> = handlers.values            .filterIsInstance<ReversibleHandler<*>>()            .associateBy { it.id }        return PersistentUndoStack(dao, SystemOperationSerializer, byId)    }    @Provides @Singleton    fun provideAtomicBatchCoordinator(        executor: SystemOperationExecutorImpl,        handlers: Map<Class<out SystemOperation>, @JvmSuppressWildcards SystemOperationHandler<*>>,    ): AtomicBatchCoordinator = AtomicBatchCoordinator(executor, handlers)    // ─── Facade ───────────────────────────────────────────────────────────    @Provides @Singleton    fun provideSystemFacade(        executor: SystemOperationExecutorImpl, undoStack: PersistentUndoStack,        batchCoordinator: AtomicBatchCoordinator, notificationHandler: NotificationHandler,    ): SystemFacade = SystemFacade(executor, undoStack, batchCoordinator, notificationHandler)}
